const HAND_SIZE = 10;
const MAX_SWAPS = 3;
const THEME_KEY = "defensomania-theme";
const TIP_KEY = "defensomania-share-tip";

if (!window.CARDS) {
  document.querySelector("main").textContent =
    "Card data not found (cards-data.js). It is generated by the MkDocs build: restart mkdocs serve or run mkdocs build.";
  throw new Error("cards-data.js missing");
}

const { scenarios, activities } = window.CARDS;
const ICONS = window.ICONS;

const PHASES = [...new Set(activities.map((c) => c.phase))];

const $ = (id) => document.getElementById(id);
const scenarioEl = $("scenario");
const handEl = $("hand");
const phasesEl = $("phases");
const playDialog = $("play-dialog");
const pickDialog = $("pick-dialog");
const pickList = $("pick-list");
const pickFilter = $("pick-filter");
const state = {
  scenario: 0,
  hand: [],
  selected: null,
  swaps: MAX_SWAPS,
  covered: false,
  phases: new Set(PHASES),
  deck: [],
};

const slug = (phase) => phase.toLowerCase().replace(/\s+/g, "-");
const isJoker = (card) => /^joker\b/i.test(card.text);

function shuffle(items) {
  const a = [...items];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text) node.textContent = text;
  return node;
}

function icon(name) {
  const node = el("span", "icon");
  node.style.setProperty("--icon", `url("icons/${name}.svg")`);
  node.setAttribute("aria-hidden", "true");
  return node;
}

function svg(path) {
  const ns = "http://www.w3.org/2000/svg";
  const root = document.createElementNS(ns, "svg");
  root.setAttribute("viewBox", "0 0 24 24");
  root.setAttribute("aria-hidden", "true");
  const p = document.createElementNS(ns, "path");
  p.setAttribute("d", path);
  root.append(p);
  return root;
}

function toast(message, ms = 1800) {
  const node = $("toast");
  node.textContent = message;
  node.classList.add("show");
  clearTimeout(toast.timer);
  if (ms) toast.timer = setTimeout(() => node.classList.remove("show"), ms);
}

/* Deck state */

const pool = () => activities.flatMap((c, i) => (state.phases.has(c.phase) ? [i] : []));
const spare = () => pool().filter((i) => !state.hand.includes(i));

function drawScenario() {
  if (state.deck.length === 0) {
    state.deck = shuffle(scenarios.flatMap((c, i) => (isJoker(c) ? [] : [i])));
  }
  state.scenario = state.deck.pop();
}

function dealHand() {
  state.hand = shuffle(pool()).slice(0, HAND_SIZE);
  state.selected = null;
  state.swaps = MAX_SWAPS;
}

function updateHash() {
  history.replaceState(null, "", `#s=${state.scenario}&h=${state.hand.join(".")}`);
}

function readHash() {
  const p = new URLSearchParams(location.hash.slice(1));
  const s = Number(p.get("s"));
  const h = (p.get("h") ?? "").split(".").filter(Boolean).map(Number);
  const valid =
    p.has("s") &&
    Number.isInteger(s) && s >= 0 && s < scenarios.length &&
    h.length > 0 && h.length <= HAND_SIZE &&
    new Set(h).size === h.length &&
    h.every((i) => Number.isInteger(i) && i >= 0 && i < activities.length);
  return valid ? { s, h } : null;
}

/* Rendering */

function sourceNode(source) {
  const node = el("div", "source", "Source: ");
  if (/^https?:\/\//i.test(source)) {
    const a = el("a", "", source);
    a.href = source;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    node.append(a);
  } else {
    node.append(document.createTextNode(source));
  }
  return node;
}

function renderScenario() {
  const card = scenarios[state.scenario];
  const label = el("div", "label");
  label.append(icon("scenario"), document.createTextNode("Scenario"));
  const nodes = [label, el("div", "text", card.text)];
  if (card.source) nodes.push(sourceNode(card.source));
  scenarioEl.replaceChildren(...nodes);
  scenarioEl.classList.remove("flip");
  void scenarioEl.offsetWidth;
  scenarioEl.classList.add("flip");
}

function buildCard(idx, { pos = null, big = false } = {}) {
  const card = activities[idx];
  const node = el("div", `card activity ${slug(card.phase)}${isJoker(card) ? " joker" : ""}${big ? " big" : ""}`);
  const hd = el("div", "hd");
  hd.append(icon(slug(card.phase)));
  hd.append(el("span", "", card.phase));
  if (isJoker(card)) hd.append(el("span", "tag", "Joker"));
  if (pos !== null) hd.append(el("span", "num", String((pos + 1) % 10)));
  node.append(hd, el("div", "body", card.text));
  return node;
}

function renderHand({ animate = true, only = null } = {}) {
  handEl.classList.toggle("covered", state.covered);
  const nodes = state.hand.map((idx, pos) => {
    const node = buildCard(idx, { pos });
    node.tabIndex = 0;
    node.setAttribute("role", "button");
    node.style.setProperty("--i", pos);

    const swap = el("button", "swap");
    swap.type = "button";
    swap.title = "Replace this card with another one";
    swap.addEventListener("click", (e) => {
      e.stopPropagation();
      swapCard(pos);
    });
    const back = el("div", "cardback");
    back.append(svg(ICONS.logo));
    const footer = el("div", "ft");
    footer.append(swap);
    node.append(footer, back);

    if (animate && (only === null || only === pos)) {
      node.classList.add("deal");
      node.addEventListener("animationend", () => node.classList.remove("deal"), { once: true });
    }

    node.addEventListener("click", () => toggleSelect(pos));
    node.addEventListener("dblclick", () => {
      choose(pos);
      playSelected();
    });
    node.addEventListener("keydown", (e) => {
      if (e.key === " ") {
        e.preventDefault();
        e.stopPropagation();
        toggleSelect(pos);
      } else if (e.key === "Enter" && e.target === node) {
        e.preventDefault();
        e.stopPropagation();
        choose(pos);
        playSelected();
      }
    });
    return node;
  });
  handEl.replaceChildren(...nodes);
  syncHand();
}

function syncHand() {
  handEl.classList.toggle("has-selection", state.selected !== null);
  const noSpare = spare().length === 0;
  [...handEl.children].forEach((node, pos) => {
    const selected = pos === state.selected;
    node.classList.toggle("selected", selected);
    node.setAttribute("aria-pressed", String(selected));
    const swap = node.querySelector(".swap");
    swap.textContent = `Swap (${state.swaps})`;
    swap.disabled = state.covered || state.swaps === 0 || noSpare;
  });
  $("play").disabled = state.selected === null || state.covered;
  $("cover").textContent = state.covered ? "Reveal cards" : "Cover cards";
  $("cover").setAttribute("aria-pressed", String(state.covered));
}

function renderPhases() {
  const all = state.phases.size === PHASES.length;
  const allChip = el("button", "chip", "All phases");
  allChip.type = "button";
  allChip.setAttribute("aria-pressed", String(all));
  allChip.addEventListener("click", () => setPhases(new Set(PHASES)));

  const chips = PHASES.map((phase) => {
    const chip = el("button", `chip ${slug(phase)}`);
    chip.type = "button";
    chip.title = all ? "Deal only this phase" : "Add or remove this phase";
    chip.setAttribute("aria-pressed", String(!all && state.phases.has(phase)));
    chip.append(icon(slug(phase)));
    chip.append(document.createTextNode(phase));
    chip.addEventListener("click", () => togglePhase(phase));
    return chip;
  });
  phasesEl.replaceChildren(allChip, ...chips);
}

/* Actions */

function newRound() {
  drawScenario();
  dealHand();
  renderScenario();
  renderHand();
  updateHash();
}

function redeal() {
  dealHand();
  renderHand();
  updateHash();
}

function setPhases(phases) {
  state.phases = phases;
  renderPhases();
  redeal();
}

function togglePhase(phase) {
  if (state.phases.size === PHASES.length) {
    setPhases(new Set([phase]));
    return;
  }
  const next = new Set(state.phases);
  if (!next.delete(phase)) next.add(phase);
  setPhases(next.size === 0 ? new Set(PHASES) : next);
}

function choose(pos) {
  if (state.covered || pos >= state.hand.length) return;
  state.selected = pos;
  syncHand();
}

function toggleSelect(pos) {
  if (state.covered) return;
  state.selected = state.selected === pos ? null : pos;
  syncHand();
}

function swapCard(pos) {
  const candidates = spare();
  if (state.covered || state.swaps === 0 || candidates.length === 0) return;
  state.hand[pos] = candidates[Math.floor(Math.random() * candidates.length)];
  state.swaps--;
  state.selected = null;
  renderHand({ only: pos });
  updateHash();
}

function toggleCover() {
  state.covered = !state.covered;
  if (state.covered) state.selected = null;
  handEl.classList.toggle("covered", state.covered);
  syncHand();
}

function promptFor(card) {
  if (isJoker(card)) return "Joker: describe your own idea for this phase and how you would implement it.";
  if (card.phase === "Prepare") return "What should have been in place to be ready for this scenario?";
  if (card.phase === "Detect") return "How could you identify the attack, or the malicious activity happening right now?";
  return "How would you respond to the incident, and how would you implement this activity in your environment?";
}

function playSelected() {
  if (state.selected === null || state.covered || playDialog.open) return;
  const idx = state.hand[state.selected];
  const recap = el("p", "recap", scenarios[state.scenario].text);
  $("play-content").replaceChildren(recap, buildCard(idx, { big: true }), el("p", "prompt", promptFor(activities[idx])));
  playDialog.showModal();
}

/* Scenario picker */

function renderPickList(query) {
  const needle = query.trim().toLowerCase();
  const items = scenarios.flatMap((card, i) => (!needle || card.text.toLowerCase().includes(needle) ? [[card, i]] : []));
  if (items.length === 0) {
    pickList.replaceChildren(el("li", "empty", "No scenario matches."));
    return;
  }
  pickList.replaceChildren(
    ...items.map(([card, i]) => {
      const li = el("li");
      const btn = el("button", "", card.text);
      btn.type = "button";
      btn.addEventListener("click", () => setScenario(i));
      li.append(btn);
      return li;
    })
  );
}

function setScenario(i) {
  state.scenario = i;
  renderScenario();
  updateHash();
  pickDialog.close();
}

function openPicker() {
  if (pickDialog.open) return;
  pickFilter.value = "";
  renderPickList("");
  pickDialog.showModal();
  pickFilter.focus();
}

pickFilter.addEventListener("input", () => renderPickList(pickFilter.value));
$("pick-random").addEventListener("click", () => {
  drawScenario();
  setScenario(state.scenario);
});

for (const dialog of [playDialog, pickDialog]) {
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });
}

/* Sharing, theme, presentation */

function markTipSeen() {
  try {
    localStorage.setItem(TIP_KEY, "1");
  } catch {
    // Storage can be blocked; the tip then simply shows again next visit.
  }
}

async function copyLink() {
  updateHash();
  markTipSeen();
  try {
    await navigator.clipboard.writeText(location.href);
    toast("Link copied");
  } catch {
    window.prompt("Copy this link:", location.href);
  }
}

function toggleTheme() {
  const root = document.documentElement;
  const dark = (root.dataset.theme || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")) === "dark";
  const next = dark ? "light" : "dark";
  root.dataset.theme = next;
  try {
    localStorage.setItem(THEME_KEY, next);
  } catch {
    // Storage can be blocked; the theme then only lasts for this visit.
  }
}

function toggleFullscreen() {
  if (document.fullscreenElement) document.exitFullscreen();
  else document.documentElement.requestFullscreen?.().catch(() => {});
}

document.addEventListener("fullscreenchange", () => {
  document.body.classList.toggle("present", Boolean(document.fullscreenElement));
  document.body.classList.remove("idle");
});

let idleTimer;
document.addEventListener("mousemove", () => {
  document.body.classList.remove("idle");
  clearTimeout(idleTimer);
  if (document.body.classList.contains("present")) {
    idleTimer = setTimeout(() => document.body.classList.add("idle"), 3000);
  }
});

/* Keyboard */

document.addEventListener("keydown", (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const dialogOpen = playDialog.open || pickDialog.open;
  if (e.key === "Escape") {
    if (!dialogOpen && state.selected !== null) {
      state.selected = null;
      syncHand();
    }
    return;
  }
  if (dialogOpen || /^(input|textarea|select)$/i.test(e.target.tagName)) return;

  if (/^[0-9]$/.test(e.key)) {
    choose(e.key === "0" ? 9 : Number(e.key) - 1);
    return;
  }
  if (e.key === "Enter") {
    if (!e.target.closest("button, a, .card")) playSelected();
    return;
  }
  const actions = {
    n: newRound,
    r: redeal,
    p: openPicker,
    c: toggleCover,
    l: copyLink,
    f: toggleFullscreen,
    t: toggleTheme,
  };
  const action = actions[e.key.toLowerCase()];
  if (action) {
    e.preventDefault();
    action();
  }
});

$("new-scenario").addEventListener("click", newRound);
$("redeal").addEventListener("click", redeal);
$("pick-scenario").addEventListener("click", openPicker);
$("play").addEventListener("click", playSelected);
$("cover").addEventListener("click", toggleCover);
$("copy-link").addEventListener("click", copyLink);
$("theme").addEventListener("click", toggleTheme);
$("fullscreen").addEventListener("click", toggleFullscreen);

const moreBtn = $("more");
const moreMenu = $("more-menu");
function setMenu(open) {
  moreMenu.hidden = !open;
  moreBtn.setAttribute("aria-expanded", String(open));
}
moreBtn.addEventListener("click", () => setMenu(moreMenu.hidden));
moreMenu.addEventListener("click", () => setMenu(false));
document.addEventListener("click", (e) => {
  if (!e.target.closest(".more")) setMenu(false);
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !moreMenu.hidden) {
    setMenu(false);
    moreBtn.focus();
  }
});
// iPhones do not support the Fullscreen API.
if (!document.documentElement.requestFullscreen) $("fullscreen").hidden = true;

/* Start */

function loadFromHash() {
  const shared = readHash();
  if (shared) {
    state.scenario = shared.s;
    state.hand = shared.h;
    state.selected = null;
    state.swaps = MAX_SWAPS;
    renderScenario();
    renderHand();
  } else {
    newRound();
  }
}

try {
  const stored = localStorage.getItem(THEME_KEY);
  if (stored) document.documentElement.dataset.theme = stored;
} catch {
  // Storage can be blocked; fall back to the system theme.
}

window.addEventListener("hashchange", () => {
  if (readHash()) loadFromHash();
});

renderPhases();
loadFromHash();
updateHash();

let tipSeen = false;
try {
  tipSeen = Boolean(localStorage.getItem(TIP_KEY));
} catch {
  // Storage can be blocked; show the tip.
}
if (!tipSeen) {
  const tip = $("tip");
  tip.hidden = false;
  tip.addEventListener("click", () => {
    tip.hidden = true;
    markTipSeen();
  });
}

if ("serviceWorker" in navigator && location.protocol.startsWith("http")) {
  navigator.serviceWorker.register("sw.js").catch(() => {});
}
